(()=>{const list=document.querySelector('#variant-list'),add=document.querySelector('#add-variant'),expandAll=document.querySelector('#expand-all-variants');if(!list||!add||!expandAll)return;const cards=()=>[...list.querySelectorAll('.variant-card')];const closeOthers=current=>{if(expandAll.checked)return;cards().forEach(card=>card.classList.toggle('is-expanded',card===current))};const bind=card=>{if(card.dataset.accordionBound)return;card.dataset.accordionBound='1';const header=card.querySelector(':scope > header'),title=header.querySelector('span'),color=card.querySelector('[data-variant-color]'),swatch=card.querySelector('input[type="color"]');const summary=document.createElement('span');summary.className='variant-summary';summary.innerHTML='<i class="variant-summary-swatch"></i><b></b>';title.prepend(summary);const update=()=>{summary.querySelector('b').textContent=color.value.trim()||'New colour';summary.querySelector('i').style.background=swatch.value||'#777777'};color.addEventListener('input',update);swatch.addEventListener('input',update);header.addEventListener('click',event=>{if(event.target.closest('button,input,label'))return;if(expandAll.checked)return;const opening=!card.classList.contains('is-expanded');cards().forEach(item=>item.classList.remove('is-expanded'));if(opening)card.classList.add('is-expanded')});update()};cards().forEach((card,index)=>{bind(card);card.classList.toggle('is-expanded',index===0)});add.addEventListener('click',()=>{const card=cards().at(-1);if(!card)return;bind(card);closeOthers(card);card.scrollIntoView({behavior:'smooth',block:'nearest'})});expandAll.addEventListener('change',()=>{if(expandAll.checked)cards().forEach(card=>card.classList.add('is-expanded'));else if(cards().length)closeOthers(cards()[0])})})();
