(()=>{const list=document.querySelector('#variant-list'),addVariant=document.querySelector('#add-variant');if(!list)return;const arrange=card=>{const grid=card.querySelector('.variant-grid'),section=card.querySelector('.size-inventory'),firstRow=section?.querySelector(':scope > .size-stock-row'),size=firstRow?.querySelector('[data-variant-size]')?.closest('label'),stock=firstRow?.querySelector('[name$="[stock]"]')?.closest('label')||grid.querySelector(':scope > .colour-stock-field'),sku=card.querySelector('[data-variant-sku]')?.closest('label'),enabled=firstRow?.querySelector(':scope > .check-card')||grid.querySelector(':scope > .variant-enabled-field'),addSize=card.querySelector('.add-size');if(!grid||!section||!firstRow||!stock||!sku||!enabled||!addSize)return;sku.classList.add('variant-sku-field');enabled.classList.add('variant-enabled-field');stock.classList.add('colour-stock-field');grid.insertBefore(sku,section);grid.insertBefore(enabled,section);let action=grid.querySelector(':scope > .variant-size-action');if(!action){action=document.createElement('div');action.className='variant-size-action wide';grid.insertBefore(action,section)}action.append(addSize);if(card.classList.contains('has-sizes')){firstRow.insertBefore(size,firstRow.firstChild);firstRow.insertBefore(stock,size.nextSibling)}else{grid.insertBefore(stock,sku);section.hidden=true}section.hidden=!card.classList.contains('has-sizes')};const observe=card=>{if(card.dataset.inventoryLayoutBound)return;card.dataset.inventoryLayoutBound='1';arrange(card);new MutationObserver(()=>arrange(card)).observe(card,{attributes:true,attributeFilter:['class']})};list.querySelectorAll('.variant-card').forEach(observe);addVariant?.addEventListener('click',()=>{const card=list.querySelector('.variant-card:last-child');if(card)observe(card)});new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===1&&node.matches?.('.variant-card'))observe(node)}))).observe(list,{childLis