(()=>{let timer;document.addEventListener('input',event=>{const input=event.target.closest('[data-vendor-code]');if(!input)return;clearTimeout(timer);const status=input.parentElement.querySelector('[data-vendor-status]');status.textContent='';status.className='vendor-code-status';if(!input.value.trim())return;timer=setTimeout(async()=>{const params=new URLSearchParams({code:input.value.trim(),exclude_product_id:input.dataset.excludeProduct||'',exclude_variant_id:input.dataset.excludeVariant||''});const result=await fetch(`{{ route('admin.vendor-code.check') }}?${params}`,{headers:{Accept:'application/json'}}).then(response=>response.json());if(result.exists){status.classList.add('is-error');status.innerHTML=`Already used by <a href="${result.url}">${result.name}</a>`}else{status.classList.add('is-ok');status.textContent='Vendor code is available'}},350)})})();
(()=>{const list=document.querySelector('#variant-list'),base=document.querySelector('#base-sku');if(!list||!base)return;const clean=value=>value.trim().toUpperCase().replace(/[^A-Z0-9]+/g,'-').replace(/^-+|-+$/g,'');const colourNames=[['Black','#000000'],['White','#ffffff'],['Red','#d32f2f'],['Pink','#d8849f'],['Maroon','#6c1f2f'],['Orange','#e67e22'],['Yellow','#e2bd32'],['Gold','#d7ad3f'],['Green','#527a25'],['Emerald','#0d5d45'],['Blue','#2456a6'],['Navy','#111d35'],['Purple','#704080'],['Brown','#6b4226'],['Beige','#c7aa78'],['Grey','#777777']];const nearest=hex=>{const rgb=[1,3,5].map(index=>parseInt(hex.slice(index,index+2),16));return colourNames.map(([name,value])=>{const target=[1,3,5].map(index=>parseInt(value.slice(index,index+2),16));return[name,target.reduce((sum,item,index)=>sum+(item-rgb[index])**2,0)]}).sort((a,b)=>a[1]-b[1])[0][0]};const updateSku=card=>{const sku=card.querySelector('[data-variant-sku]');if(!sku||sku.dataset.skuManual==='1')return;const color=card.querySelector('[data-variant-color]')?.value||'DEFAULT',size=card.querySelector('[data-variant-size]')?.value||'';sku.value=[clean(base.value)||'TB',clean(color),clean(size)].filter(Boolean).join('-')};const bind=card=>{if(card.dataset.variantAssistBound)return;card.dataset.variantAssistBound='1';const color=card.querySelector('[data-variant-color]'),swatch=card.querySelector('input[type="color"]'),sku=card.querySelector('[data-variant-sku]');if(!color||!swatch||!sku)return;sku.dataset.skuManual=sku.value.trim()?'1':'0';sku.addEventListener('input',event=>{if(event.isTrusted)sku.dataset.skuManual=sku.value.trim()?'1':'0'});color.addEventListener('input',event=>{if(event.isTrusted)color.dataset.colorManual='1';updateSku(card)});const setColour=(hex,name=nearest(hex))=>{swatch.value=hex;color.dataset.colorAuto='1';if(!color.value.trim()||color.value==='Default'||color.dataset.colorManual!=='1'){color.value=name;color.dispatchEvent(new Event('input',{bubbles:true}));color.dataset.colorManual='0'}updateSku(card)};swatch.parentElement.classList.add('variant-shade-field');swatch.dataset.variantSwatch='1';swatch.addEventListener('input',()=>setColour(swatch.value));const presets=document.createElement('div');presets.className='variant-colour-presets';presets.setAttribute('aria-label','Common colours');colourNames.slice(0,12).forEach(([name,hex])=>{const button=document.createElement('button');button.type='button';button.title=name;button.setAttribute('aria-label',name);button.style.setProperty('--preset-colour',hex);button.addEventListener('click',()=>setColour(hex,name));presets.append(button)});swatch.parentElement.append(presets);updateSku(card)};list.querySelectorAll('.variant-card').forEach(bind);base.addEventListener('input',()=>list.querySelectorAll('.variant-card').forEach(updateSku));new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===1&&node.matches?.('.variant-card'))bind(node)}))).observe(list,{childList:true})})();
(()=>{const list=document.querySelector('#variant-list');if(!list)return;const component=value=>value.toString(16).padStart(2,'0');const bind=card=>{if(card.dataset.imageColourPickerBound)return;card.dataset.imageColourPickerBound='1';const shade=card.querySelector('input[type="color"]'),field=shade?.parentElement;if(!shade||!field)return;const button=document.createElement('button');button.type='button';button.className='action-btn secondary pick-image-colour';button.innerHTML='<i data-lucide="pipette" aria-hidden="true"></i><span>Pick from image</span>';button.addEventListener('click',()=>{const active=card.classList.toggle('is-picking-colour');button.classList.toggle('active',active);button.querySelector('span').textContent=active?'Tap a product image':'Pick from image'});field.append(button);card.addEventListener('click',event=>{const image=event.target.closest('[data-gallery-preview] img,.variant-gallery-preview img');if(!image||!card.classList.contains('is-picking-colour'))return;event.preventDefault();event.stopPropagation();try{const rect=image.getBoundingClientRect(),x=Math.max(0,Math.min(image.naturalWidth-1,Math.floor((event.clientX-rect.left)*image.naturalWidth/rect.width))),y=Math.max(0,Math.min(image.naturalHeight-1,Math.floor((event.clientY-rect.top)*image.naturalHeight/rect.height))),canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(image,0,0);const pixel=context.getImageData(x,y,1,1).data;shade.value=`#${component(pixel[0])}${component(pixel[1])}${component(pixel[2])}`;shade.dispatchEvent(new Event('input',{bubbles:true}));card.classList.remove('is-picking-colour');button.classList.remove('active');button.querySelector('span').textContent='Pick from image'}catch(error){button.querySelector('span').textContent='Unable to sample this image'}});window.renderAdminIcons?.()};list.querySelectorAll('.variant-card').forEach(bind);new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===1&&node.matches?.('.variant-card'))bind(node)}))).observe(list,{childList:true})})();
(()=>{const form=document.querySelector('[data-product-editor]');if(!form)return;let submitting=false;form.addEventListener('submit',async event=>{if(submitting)return;event.preventDefault();if(!form.reportValidity())return;const oldAlert=form.querySelector('.product-form-errors');oldAlert?.remove();const submitter=event.submitter,body=new FormData(form),endpoint=form.getAttribute('action');if(submitter?.name)body.set(submitter.name,submitter.value);submitter?.setAttribute('disabled','disabled');try{const response=await fetch(endpoint,{method:'POST',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},body}),result=await response.json();if(response.status===422){const messages=Object.values(result.errors||{}).flat();const alert=document.createElement('div');alert.className='product-form-errors';alert.setAttribute('role','alert');alert.innerHTML=`<strong>Please correct these fields:</strong><ul>${messages.map(message=>`<li>${String(message).replace(/[<>&]/g,character=>({'<':'&lt;','>':'&gt;','&':'&amp;'}[character]))}</li>`).join('')}</ul>`;form.prepend(alert);alert.scrollIntoView({behavior:'smooth',block:'center'});return}if(!response.ok||!result.redirect)throw new Error(result.message||'Product could not be saved. Please try again.');submitting=true;window.location.href=result.redirect}catch(error){const alert=document.createElement('div');alert.className='product-form-errors';alert.textContent=error.message;form.prepend(alert);alert.scrollIntoView({behavior:'smooth',block:'center'})}finally{submitter?.removeAttribute('disabled')}})})();
(()=>{const describe=hex=>{const red=parseInt(hex.slice(1,3),16)/255,green=parseInt(hex.slice(3,5),16)/255,blue=parseInt(hex.slice(5,7),16)/255,max=Math.max(red,green,blue),min=Math.min(red,green,blue),light=(max+min)/2,delta=max-min;let hue=0,saturation=0;if(delta){saturation=delta/(1-Math.abs(2*light-1));if(max===red)hue=60*(((green-blue)/delta)%6);else if(max===green)hue=60*((blue-red)/delta+2);else hue=60*((red-green)/delta+4);if(hue<0)hue+=360}if(light<0.09)return'Black';if(light>0.94)return'White';if(saturation<0.1)return light<0.3?'Charcoal':light<0.68?'Grey':'Light Grey';if(saturation<0.22){if(hue>=35&&hue<75)return light<0.48?'Taupe':'Beige';if(hue>=75&&hue<170)return light<0.45?'Olive Grey':'Sage';if(hue>=170&&hue<250)return light<0.45?'Slate':'Blue Grey';if(hue>=250&&hue<345)return light<0.5?'Mauve':'Dusty Pink'}const tone=light<0.28?'Dark ':light>0.76?'Light ':'';if(hue<12||hue>=350)return light<0.38?'Maroon':tone+'Red';if(hue<25)return light<0.45?'Rust':tone+'Orange';if(hue<45)return light<0.58?'Brown':'Peach';if(hue<65)return saturation<0.55?'Gold':'Yellow';if(hue<90)return light<0.45?'Olive':'Lime';if(hue<155)return tone+'Green';if(hue<180)return light<0.48?'Teal':'Mint';if(hue<205)return'Turquoise';if(hue<250)return tone+'Blue';if(hue<275)return light<0.4?'Navy':'Indigo';if(hue<305)return tone+'Purple';if(hue<335)return light<0.55?'Magenta':'Pink';return light<0.5?'Burgundy':'Rose'};document.addEventListener('input',event=>{const shade=event.target.closest('[data-variant-swatch]');if(!shade)return;const colour=shade.closest('.variant-card')?.querySelector('[data-variant-color]');if(!colour||colour.dataset.colorManual==='1')return;colour.value=describe(shade.value);colour.dispatchEvent(new Event('input',{bubbles:true}));colour.dataset.colorManual='0'})})();
(()=>{const list=document.querySelector('#variant-list'),category=document.querySelector('#product-category');if(!list||!category)return;const round=value=>Math.max(0,Math.round(value/50)*50);const calculate=card=>{const cost=card.querySelector('[name$="[cost_price]"]'),full=card.querySelector('[data-regular-price]'),sale=card.querySelector('[data-sale-price]');if(!cost||!full||!sale||cost.value==='')return;const option=category.selectedOptions[0],costValue=Number(cost.value)||0,margin=Number(option?.dataset.marginValue)||0,discount=Number(option?.dataset.discountValue)||0;let saleValue=option?.dataset.marginType==='percentage'?costValue*(1+margin/100):costValue+margin;let fullValue=option?.dataset.discountType==='percentage'&&discount>0?saleValue/(1-Math.min(discount,99.99)/100):saleValue+discount;saleValue=round(saleValue);fullValue=round(fullValue);if(sale.dataset.priceManual!=='1')sale.value=saleValue.toFixed(2);if(full.dataset.priceManual!=='1')full.value=fullValue.toFixed(2);sale.dispatchEvent(new Event('input',{bubbles:true}));full.dispatchEvent(new Event('input',{bubbles:true}))};const bind=card=>{if(card.dataset.categoryPricingBound)return;card.dataset.categoryPricingBound='1';const cost=card.querySelector('[name$="[cost_price]"]'),full=card.querySelector('[data-regular-price]'),sale=card.querySelector('[data-sale-price]');full?.addEventListener('input',event=>{if(event.isTrusted)full.dataset.priceManual='1'});sale?.addEventListener('input',event=>{if(event.isTrusted)sale.dataset.priceManual='1'});cost?.addEventListener('input',()=>calculate(card))};list.querySelectorAll('.variant-card').forEach(bind);new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===1&&node.matches?.('.variant-card'))bind(node)}))).observe(list,{childList:true});category.addEventListener('change',()=>list.querySelectorAll('.variant-card').forEach(card=>{card.querySelector('[data-regular-price]')?.removeAttribute('data-price-manual');card.querySelector('[data-sale-price]')?.removeAttribute('data-price-manual');calculate(card)}))})();
(()=>{let timer;document.addEventListener('input',event=>{const code=event.target.closest('[data-vendor-code]');if(!code)return;clearTimeout(timer);timer=setTimeout(async()=>{const vendor=document.querySelector('#product-vendor')?.value.trim();if(!vendor||!code.value.trim())return;const params=new URLSearchParams({code:code.value.trim(),vendor_name:vendor,exclude_product_id:code.dataset.excludeProduct||'',exclude_variant_id:code.dataset.excludeVariant||''}),result=await fetch(`{{ route('admin.vendor-code.check') }}?${params}`,{headers:{Accept:'application/json'}}).then(response=>response.json());if(!result.exists||!result.variant)return;const card=code.closest('.variant-card'),fields={cost_price:result.variant.cost_price,regular_price:result.variant.regular_price,sale_price:result.variant.sale_price,stock:result.variant.stock,vendor_reference:result.variant.vendor_reference};Object.entries(fields).forEach(([name,value])=>{if(value===null||value==='')return;const input=card.querySelector(`[name$="[${name}]"]`);if(input){input.value=value;input.dispatchEvent(new Event('input',{bubbles:true}))}});const status=code.parentElement.querySelector('[data-vendor-status]');status.className='vendor-code-status is-ok';status.innerHTML=`Existing vendor record loaded. Saving will update <a href="${result.url}">${result.name}</a>.`},450)})})();
</script>@endpush
